  static List<GroupItem> search(String query, {int limit = 40}) {
    if (query.trim().isEmpty) return popularGroups;
    final clean = query.trim().toLowerCase().replaceAll(RegExp(r'[^a-zа-я0-9]'), '');
    final results = <GroupItem>[];
    for (final entry in allGroups.entries) {
      final norm = entry.key.toLowerCase().replaceAll(RegExp(r'[^a-zа-я0-9]'), '');
      if (norm.contains(clean)) {
        results.add(GroupItem(title: entry.key, uuid: entry.value));
        if (results.length >= limit) break;
      }
    }
    return results;
  }

  static GroupItem? findByTitle(String title) {
    final uuid = allGroups[title];
    if (uuid != null) return GroupItem(title: title, uuid: uuid);
    return null;
  }
}
